SELECT 
FROM questions q LEFT JOIN categories c ON q.category_id = c.category_id

    AND q.category_id = #{param.categoryId}
    AND q.difficulty = #{param.difficulty}

        AND EXISTS (
            SELECT 1 FROM question_tags qt
            JOIN tags t ON qt.tag_id = t.tag_id
            WHERE qt.question_id = q.question_id AND t.name = #{param.tag}
        )


ORDER BY q.question_id
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM questions q

    AND q.category_id = #{param.categoryId}
    AND q.difficulty = #{param.difficulty}

        AND EXISTS (
            SELECT 1 FROM question_tags qt
            JOIN tags t ON qt.tag_id = t.tag_id
            WHERE qt.question_id = q.question_id AND t.name = #{param.tag}
        )

